| `create.body.prompt` | `{"$ref":"request.prompt"}` |
| `create.body.negative_prompt` | `{"$omitEmpty":{"$ref":"request.providerOptions.stability-image.negative_prompt"}}` |
| `create.body.aspect_ratio` | `{"$omitEmpty":{"$ref":"request.aspectRatio"}}` |
| `create.body.output_format` | `{"$coalesce":[{"$ref":"request.output.format"},{"$ref":"request.providerOptions.stability-image.output_format"},"png"]}` |
