## Manifest 完整接口定义

以下 JSON 与插件包内实际 `manifest.json` 逐字段一致，覆盖插件身份、权限、配置、鉴权、参数、校验、创建、Agent、查询、取消、结果下载、响应和 Agent 响应映射。`documentation` 字段的值就是当前完整文档；为避免文档在自身内部无限递归，JSON 中仅用等义占位文本表示正文。

```json
{
  "apiVersion": "yingce.plugin/v2",
  "id": "stability-image",
  "name": "Stability AI Image",
  "version": "2.0.0",
  "author": "Stability AI / 影策",
  "description": "Stability AI Image 独立请求协议插件。",
  "documentation": "<当前插件的完整 documentation，由 README.md 与 docs/interface.md 拼接而成；为避免 JSON 递归，此处不重复展开正文。>",
  "permissions": [
    "generation.run",
    "media.read"
  ],
  "configuration": {
    "fields": [
      {
        "name": "apiKey",
        "type": "secret",
        "label": "API Key",
        "required": true
      }
    ]
  },
  "contributes": {
    "providers": [
      {
        "id": "stability-image",
        "label": "Stability AI Image",
        "capabilities": [
          "image"
        ],
        "scopes": [
          "admin.system-channel",
          "user.custom-channel",
          "canvas",
          "creation",
          "agent"
        ],
        "baseUrl": "https://api.stability.ai",
        "requiresPublicMediaUrls": false,
        "auth": {
          "type": "bearer",
          "field": "apiKey"
        },
        "parameters": [
          {
            "name": "model",
            "type": "string",
            "required": true,
            "mapping": "model",
            "description": "图片模型 ID。"
          },
          {
            "name": "prompt",
            "type": "string",
            "required": true,
            "mapping": "prompt",
            "description": "图片提示词。"
          },
          {
            "name": "images",
            "type": "media[]",
            "required": false,
            "mapping": "provider image/reference fields",
            "description": "参考图或编辑源图，role 由业务层确定。"
          },
          {
            "name": "imageCount",
            "type": "integer",
            "required": false,
            "mapping": "n/sample_count",
            "description": "输出数量。"
          },
          {
            "name": "aspectRatio",
            "type": "string",
            "required": false,
            "mapping": "size/aspect_ratio",
            "description": "比例或尺寸，语义按协议说明。"
          },
          {
            "name": "resolution",
            "type": "string",
            "required": false,
            "mapping": "resolution/imageSize",
            "description": "分辨率档位。"
          },
          {
            "name": "quality",
            "type": "string",
            "required": false,
            "mapping": "quality",
            "description": "质量档位。"
          },
          {
            "name": "providerOptions",
            "type": "object",
            "required": false,
            "mapping": "provider-specific fields",
            "description": "插件命名空间内的厂商扩展字段。"
          }
        ],
        "create": {
          "method": "POST",
          "pathTemplate": {
            "$coalesce": [
              {
                "$ref": "request.providerOptions.stability-image.endpoint"
              },
              "/v2beta/stable-image/generate/core"
            ]
          },
          "contentType": "multipart/form-data",
          "headers": {
            "Accept": "application/json"
          },
          "body": {
            "prompt": {
              "$ref": "request.prompt"
            },
            "negative_prompt": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.stability-image.negative_prompt"
              }
            },
            "aspect_ratio": {
              "$omitEmpty": {
                "$ref": "request.aspectRatio"
              }
            },
            "output_format": {
              "$coalesce": [
                {
                  "$ref": "request.output.format"
                },
                {
                  "$ref": "request.providerOptions.stability-image.output_format"
                },
                "png"
              ]
            },
            "seed": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.stability-image.seed"
              }
            },
            "style_preset": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.stability-image.style_preset"
              }
            },
            "strength": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.stability-image.strength"
              }
            },
            "cfg_scale": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.stability-image.cfg_scale"
              }
            },
            "grow_mask": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.stability-image.grow_mask"
              }
            },
            "creativity": {
              "$omitEmpty": {
                "$ref": "request.providerOptions.stability-image.creativity"
              }
            }
          },
          "files": [
            {
              "name": "image",
              "source": {
                "$first": {
                  "$filter": {
                    "from": {
                      "$sortByOrder": {
                        "$ref": "request.images"
                      }
                    },
                    "as": "media",
                    "where": {
                      "$in": [
                        {
                          "$ref": "media.role"
                        },
                        [
                          "edit_source",
                          "reference_image",
                          ""
                        ]
                      ]
                    }
                  }
                }
              },
              "filename": "image.png"
            },
            {
              "name": "mask",
              "source": {
                "$first": {
                  "$filter": {
                    "from": {
                      "$sortByOrder": {
                        "$ref": "request.images"
                      }
                    },
                    "as": "media",
                    "where": {
                      "$in": [
                        {
                          "$ref": "media.role"
                        },
                        [
                          "mask"
                        ]
                      ]
                    }
                  }
                }
              },
              "filename": "mask.png"
            }
          ]
        },
        "response": {
          "status": {
            "$if": {
              "condition": {
                "$ref": "response.errors"
              },
              "then": "failed",
              "else": "succeeded"
            }
          },
          "message": {
            "$coalesce": [
              {
                "$ref": "response.errors"
              },
              {
                "$ref": "response.message"
              }
            ]
          },
          "images": {
            "$if": {
              "condition": {
                "$ref": "response.image"
              },
              "then": [
                {
                  "dataUrl": {
                    "$concat": [
                      "data:",
                      {
                        "$coalesce": [
                          {
                            "$ref": "response.mime_type"
                          },
                          "image/png"
                        ]
                      },
                      ";base64,",
                      {
                        "$ref": "response.image"
                      }
                    ]
                  }
                }
              ],
              "else": null
            }
          },
          "errorPaths": [
            "errors"
          ]
        }
      }
    ]
  }
}
```
